mapper.select:
SELECT * FROM ( SELECT ROWNUM AS rn, t.* FROM ( SELECT u.userIdx, u.userId, u.name, u.nickname, u.email, u.tel, u.status, u.createdDate, u.lastLoginDate, u.profile_photo, u.score, u.userLevel, u.batonpoint, a.authority FROM users u LEFT JOIN userAuthority a ON u.userId = a.userId
AND u.userId LIKE '%' || #{kwd} || '%' AND u.nickname LIKE '%' || #{kwd} || '%' AND u.email LIKE '%' || #{kwd} || '%' AND (u.userId LIKE '%' || #{kwd} || '%' OR u.nickname LIKE '%' || #{kwd} || '%')
AND u.status = #{status}
ORDER BY u.createdDate DESC ) t WHERE ROWNUM <= #{offset} + #{pageSize} ) WHERE rn > #{offset}

SELECT COUNT(*) FROM users u
AND u.userId LIKE '%' || #{kwd} || '%' AND u.nickname LIKE '%' || #{kwd} || '%' AND u.email LIKE '%' || #{kwd} || '%' AND (u.userId LIKE '%' || #{kwd} || '%' OR u.nickname LIKE '%' || #{kwd} || '%')
AND u.status = #{status}

SELECT * FROM ( SELECT ROWNUM AS rn, t.* FROM ( SELECT s.sanctionIdx, s.userIdx, s.reason, s.sanctionType, TO_CHAR(s.startDate, 'YYYY-MM-DD') AS startDate, TO_CHAR(s.endDate, 'YYYY-MM-DD') AS endDate, TO_CHAR(s.createdDate, 'YYYY-MM-DD HH24:MI') AS createdDate, s.isLifted, s.liftReason, u.userId, u.nickname, u.email FROM adminSanction s JOIN users u ON s.userIdx = u.userIdx
AND (u.userId LIKE '%' || #{kwd} || '%' OR u.nickname LIKE '%' || #{kwd} || '%')
ORDER BY s.createdDate DESC ) t WHERE ROWNUM <= #{offset} + #{pageSize} ) WHERE rn > #{offset}

mapper.update:
UPDATE adminSanction
SET isLifted = 1, liftReason = #{liftReason}, liftDate = CURRENT_TIMESTAMP
WHERE sanctionIdx = #{sanctionIdx}

mapper.select:
SELECT * FROM ( SELECT ROWNUM AS rn, t.* FROM ( SELECT w.withdrawIdx, w.userIdx, w.reason, TO_CHAR(w.requestDate, 'YYYY-MM-DD HH24:MI') AS requestDate, w.withdrawStatus, u.userId, u.nickname, u.email, u.createdDate FROM withdrawRequest w JOIN users u ON w.userIdx = u.userIdx
AND (u.userId LIKE '%' || #{kwd} || '%' OR u.nickname LIKE '%' || #{kwd} || '%')
ORDER BY w.requestDate DESC ) t WHERE ROWNUM <= #{offset} + #{pageSize} ) WHERE rn > #{offset}

mapper.update:
UPDATE withdrawRequest
SET withdrawStatus = #{withdrawStatus}, processDate = CURRENT_TIMESTAMP
WHERE withdrawIdx = #{withdrawIdx}
